<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function xw_appt_booking_card( $row, $nonce, $view = 'upcoming', $days = null ) {
    $date = ( new DateTimeImmutable( $row['starts_at'], new DateTimeZone( 'UTC' ) ) )->setTimezone( new DateTimeZone( $row['timezone'] ) );
    $fields = xw_appt_record_fields( $row ); $statuses = xw_appt_statuses();
    $ready = xw_appt_can_rebook_row( $row, xw_appt_rebook_cutoff( '', $days ) );
    $kind = 'rebook' === $view ? 'rebook' : $row['status'];
    $whatsapp = xw_appt_whatsapp_url( $row['phone'], xw_appt_settings()['whatsapp_country_code'] );
    $whatsapp = $whatsapp ? $whatsapp . '?text=' . rawurlencode( xw_appt_message_text( $row, $kind ) ) : '';
    $email = is_email( $row['email'] ); $can_move = in_array( $row['status'], array( 'pending', 'confirmed' ), true );
    $id = (int) $row['id']; $card_id = 'xw-booking-' . $id;
    $changed = empty( $row['status_changed_at'] ) ? '' : ( new DateTimeImmutable( $row['status_changed_at'], new DateTimeZone( 'UTC' ) ) )->setTimezone( wp_timezone() )->format( 'Y-m-d\TH:i' );
    ob_start(); ?>
    <article class="xw-appt-booking" data-booking="<?php echo $id; ?>" data-status="<?php echo esc_attr( $row['status'] ); ?>" data-start="<?php echo esc_attr( $row['starts_at'] ); ?>" aria-labelledby="<?php echo esc_attr( $card_id ); ?>">
        <header class="xw-appt-booking-header"><h3 id="<?php echo esc_attr( $card_id ); ?>"><?php echo esc_html( $row['customer_name'] ?: xw_t( 'Sin nombre', 'No name' ) ); ?></h3><span class="xw-appt-badge"><?php echo esc_html( $statuses[ $row['status'] ] ?? $row['status'] ); ?></span></header>
        <dl class="xw-appt-booking-meta"><div><dt><?php echo esc_html( xw_t( 'Fecha y hora', 'Date and time' ) ); ?></dt><dd class="xw-appt-booking-date"><?php echo esc_html( $date->format( 'd/m/Y H:i' ) ); ?></dd></div></dl>
        <p class="xw-appt-booking-zone"><span><?php echo esc_html( $row['timezone'] ); ?></span> · #<?php echo $id; ?></p>
        <dl class="xw-appt-booking-fields"><?php foreach ( $fields as $field ) { if ( 'appointment' === ( $field['role'] ?? '' ) || 'customer_name' === ( $field['contact_role'] ?? '' ) || '' === trim( $field['value'] ) ) { continue; } echo '<div><dt>' . esc_html( $field['label'] ) . '</dt><dd>' . nl2br( esc_html( $field['value'] ), false ) . '</dd></div>'; } ?></dl>
        <?php if ( $row['form_name'] ) : ?><p class="xw-appt-form-name"><?php echo esc_html( $row['form_name'] ); ?></p><?php endif; ?>
        <?php if ( $row['phone'] && ! $whatsapp ) : ?><p class="description"><?php echo esc_html( xw_t( 'Revisa el teléfono o su código de país para habilitar WhatsApp.', 'Check the phone or country code to enable WhatsApp.' ) ); ?></p><?php endif; ?>
        <?php if ( $row['email'] && ! $email ) : ?><p class="description"><?php echo esc_html( xw_t( 'Corrige el correo para habilitar el envío.', 'Correct the email to enable sending.' ) ); ?></p><?php endif; ?>
        <div class="xw-appt-booking-actions">
            <?php // The base is the fixed https://wa.me/ plus validated digits; preserve encoded message line breaks (esc_url removes %0A).
            if ( $whatsapp ) : ?><a class="button button-primary" href="<?php echo esc_attr( $whatsapp ); ?>" target="_blank" rel="noopener noreferrer">WhatsApp<span class="screen-reader-text"><?php echo esc_html( xw_t( ' (abre otra pestaña)', ' (opens a new tab)' ) ); ?></span></a><?php endif; ?>
            <?php if ( $email ) : ?><button type="button" class="button xw-appt-email-open" data-kind="<?php echo esc_attr( $kind ); ?>"><?php echo esc_html( xw_t( 'Correo', 'Email' ) ); ?></button><?php endif; ?>
            <?php if ( $ready || $can_move ) : ?><button type="button" class="button xw-appt-reschedule-toggle" aria-expanded="false" aria-controls="xw-reschedule-<?php echo $id; ?>"><?php echo esc_html( $ready ? xw_t( 'Reagendar', 'Rebook' ) : xw_t( 'Cambiar fecha', 'Change date' ) ); ?></button><?php endif; ?>
            <button type="button" class="button xw-appt-edit-toggle" aria-expanded="false" aria-controls="xw-details-<?php echo $id; ?>"><?php echo esc_html( xw_t( 'Editar datos', 'Edit details' ) ); ?></button>
        </div>
        <?php if ( $ready || $can_move ) : ?><form id="xw-reschedule-<?php echo $id; ?>" class="xw-appt-reschedule" data-operation="<?php echo $ready ? 'rebook' : 'reschedule'; ?>" data-nonce="<?php echo esc_attr( $nonce ); ?>" data-booking="<?php echo $id; ?>" hidden>
            <input type="hidden" name="booking_view" value="<?php echo esc_attr( $view ); ?>"><input type="hidden" name="rebook_after" value="<?php echo (int) ( $days ?? xw_appt_settings()['rebook_days'] ); ?>">
            <label for="xw-new-date-<?php echo $id; ?>"><?php echo esc_html( xw_t( 'Nueva fecha y hora', 'New date and time' ) ); ?></label>
            <div class="xw-appointment" data-xw-appointment data-xw-appointment-action="<?php echo $ready ? 'xw_appt_availability' : 'xw_appt_admin_availability'; ?>"<?php if ( ! $ready ) { echo ' data-booking="' . $id . '" data-nonce="' . esc_attr( $nonce ) . '"'; } ?>><div class="xw-appointment-date"><input id="xw-new-date-<?php echo $id; ?>" type="text" readonly autocomplete="off" inputmode="none" class="xw-appointment-date-input" placeholder="<?php echo esc_attr( xw_t( 'Selecciona fecha y hora', 'Select date and time' ) ); ?>"><button type="button" class="xw-appointment-open" aria-label="<?php echo esc_attr( xw_t( 'Abrir calendario de citas', 'Open appointment calendar' ) ); ?>"><span class="dashicons dashicons-calendar-alt" aria-hidden="true"></span></button></div><input type="hidden" class="xw-appointment-value" name="appointment" value=""></div>
            <p class="description"><?php echo esc_html( $ready ? xw_t( 'Se creará una nueva cita pendiente y se conservará esta en el historial. Se comprueba la disponibilidad; no se envían mensajes.', 'A new pending appointment is created and this one stays in history. Availability is checked; no messages are sent.' ) : xw_t( 'Se comprobará la disponibilidad al guardar. No se envían mensajes.', 'Availability is checked when saving. No messages are sent.' ) ); ?></p><button type="submit" class="button button-primary" disabled><?php echo esc_html( $ready ? xw_t( 'Crear nueva cita', 'Create new appointment' ) : xw_t( 'Guardar fecha', 'Save date' ) ); ?></button><p role="status" aria-live="polite"></p>
        </form><?php endif; ?>
        <form id="xw-details-<?php echo $id; ?>" class="xw-appt-details-form" data-nonce="<?php echo esc_attr( $nonce ); ?>" data-booking="<?php echo $id; ?>" hidden>
            <input type="hidden" name="revision" value="<?php echo esc_attr( xw_appt_record_revision( $row ) ); ?>"><input type="hidden" name="booking_view" value="<?php echo esc_attr( $view ); ?>"><input type="hidden" name="rebook_after" value="<?php echo (int) ( $days ?? xw_appt_settings()['rebook_days'] ); ?>">
            <?php foreach ( $fields as $index => $field ) : if ( 'appointment' === ( $field['role'] ?? '' ) ) { continue; } $input_id = 'xw-field-' . $id . '-' . $index; ?><label for="<?php echo esc_attr( $input_id ); ?>"><?php echo esc_html( $field['label'] ); ?></label><textarea id="<?php echo esc_attr( $input_id ); ?>" name="fields[<?php echo (int) $index; ?>]" rows="<?php echo 'textarea' === $field['type'] || str_contains( $field['value'], "\n" ) ? 3 : 1; ?>" maxlength="2000"><?php echo esc_textarea( $field['value'] ); ?></textarea><?php endforeach; ?>
            <label for="xw-name-field-<?php echo $id; ?>"><?php echo esc_html( xw_t( 'Campo usado como nombre', 'Field used as the name' ) ); ?></label><select id="xw-name-field-<?php echo $id; ?>" name="name_field"><?php foreach ( $fields as $index => $field ) { if ( 'appointment' === ( $field['role'] ?? '' ) || in_array( $field['contact_role'] ?? '', array( 'email', 'phone' ), true ) ) { continue; } echo '<option value="' . (int) $index . '" ' . selected( $field['contact_role'] ?? '', 'customer_name', false ) . '>' . esc_html( $field['label'] ) . '</option>'; } ?></select>
            <label for="xw-state-date-<?php echo $id; ?>"><?php echo esc_html( xw_t( 'Fecha del cambio de estado', 'Status change date' ) ); ?></label><input id="xw-state-date-<?php echo $id; ?>" type="datetime-local" name="status_changed_at" value="<?php echo esc_attr( $changed ); ?>" max="<?php echo esc_attr( current_datetime()->format( 'Y-m-d\TH:i' ) ); ?>"><p class="description"><?php echo esc_html( xw_t( 'Referencia para reagendar, en la zona horaria de WordPress. Las citas antiguas pueden no tenerla; indícala si la conoces.', 'Rebooking reference, in the WordPress timezone. Older appointments may not have it; enter it if known.' ) ); ?></p>
            <button type="submit" class="button button-primary" disabled><?php echo esc_html( xw_t( 'Guardar datos', 'Save details' ) ); ?></button><p role="status" aria-live="polite"></p>
        </form>
        <form class="xw-appt-booking-status" data-nonce="<?php echo esc_attr( $nonce ); ?>" data-booking="<?php echo $id; ?>"><input type="hidden" name="booking_view" value="<?php echo esc_attr( $view ); ?>"><input type="hidden" name="rebook_after" value="<?php echo (int) ( $days ?? xw_appt_settings()['rebook_days'] ); ?>"><label class="screen-reader-text" for="xw-status-<?php echo $id; ?>"><?php echo esc_html( xw_t( 'Estado de la cita', 'Appointment status' ) ); ?></label><select id="xw-status-<?php echo $id; ?>" name="status" <?php disabled( 'cancelled' === $row['status'] ); ?>><?php foreach ( $statuses as $key => $label ) { echo '<option value="' . esc_attr( $key ) . '" ' . selected( $row['status'], $key, false ) . '>' . esc_html( $label ) . '</option>'; } ?></select><button type="submit" class="button button-primary" disabled><?php echo esc_html( xw_t( 'Guardar', 'Save' ) ); ?></button><p role="status" aria-live="polite"></p></form>
        <?php if ( ! empty( $row['rebooked_to'] ) ) : ?><p class="description"><?php echo esc_html( xw_t( 'Reagendada como cita #', 'Rebooked as appointment #' ) . (int) $row['rebooked_to'] ); ?></p><?php endif; ?>
    </article>
    <?php return trim( ob_get_clean() );
}
